SELECT P.TIPO, P.JEITO, P.TITULO, P.INSTRUCAO, P.SEGUNDO, V.TITULO VIDEO, V.YT_VIDEO_ID YT, C.NOME CANAL FROM PRATICAS P JOIN VIDEO_TEMAS VT ON VT.VIDEO_ID = P.VIDEO_ID AND VT.TEMA_ID = {{temaId}} AND P.CONSELHO = 0 JOIN VIDEOS V ON V.ID = P.VIDEO_ID AND V.STATUS = 'ESTUDADO' JOIN CANAIS C ON C.ID = V.CANAL_ID ORDER BY P.ID DESC LIMIT 300